fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn median(v:&[f64])->f64{let mut v=v.to_vec();v.sort_by(f64::total_cmp);v[v.len()/2]}
fn interval(v:&[f64])->Value{assert_eq!(v.len(),15);let mut s=v.to_vec();s.sort_by(f64::total_cmp);json!({"median":s[7],"low":s[3],"high":s[11],"wins":v.iter().filter(|&&r|r<1.).count(),"all_ratios":v,"nominal_coverage":0.96484375})}
fn samples(name:&str)->(Vec<f64>,Value){let s=fs::read_to_string(format!("{R}/runs/{name}/stdout.log")).unwrap();let samples=s.lines().filter_map(|s|s.strip_prefix("SAMPLE ")).map(|s|serde_json::from_str::<Value>(s).unwrap()["ms"].as_f64().unwrap()).collect();let summary=serde_json::from_str(s.lines().find_map(|s|s.strip_prefix("SUMMARY ")).unwrap()).unwrap();(samples,summary)}
fn archive(root:&Path,dir:&Path,out:&Path,index:&mut BTreeMap<String,String>){for entry in fs::read_dir(dir).unwrap(){let e=entry.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();
    if e.file_type().unwrap().is_dir(){if ["source","target","profiles"].contains(&name.as_str()){continue;}archive(root,&p,out,index);}
    else if ["rs","md","json","log","txt","proof","public"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or(""))&&! ["close.log","close-error.log","archive-verification.log","archive.log"].contains(&name.as_str()){
        if p.to_string_lossy().contains("/loss-")&&name=="stdout.log"{continue;}let rel=p.strip_prefix(root).unwrap();let dest=out.join(rel);fs::create_dir_all(dest.parent().unwrap()).unwrap();fs::copy(&p,&dest).unwrap();index.insert(format!("artifacts/{}",rel.display()),hash(dest));}
}}
